	/**
	 * Default Constructor
	 */
    public ModelService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ModelEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ModelRepository.class) );
		this.validator		= applicationContext.getBean(ModelValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Model
	 */
		public Model createModel( CreateModelCommand command ) {

		Model entity = new Model();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setModelId( command.getModelId() );
            entity.setName( command.getName() );
            entity.setTaskDescription( command.getTaskDescription() );
            entity.setModelType( command.getModelType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Model {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateModelCommand
	 * @return		Model
	 */
	public Model updateModel( UpdateModelCommand command ) {

		Model entity = new Model();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setModelId( command.getModelId() );
            entity.setName( command.getName() );
            entity.setTaskDescription( command.getTaskDescription() );
            entity.setWorkspace( command.getWorkspace() );
            entity.setVersions( command.getVersions() );
            entity.setFeatureSets( command.getFeatureSets() );
            entity.setExperiments( command.getExperiments() );
            entity.setTags( command.getTags() );
            entity.setModelType( command.getModelType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Model {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteModelCommand
	 */
	public void delete( DeleteModelCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getModelId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Model {0} ", id );

	}

	/**
	 * Method to retrieve the Model via ModelFetchOneSummary
	 * @param 	summary ModelFetchOneSummary
	 * @return 	ModelFetchOneResponse
	 */
	public Model getModel( ModelFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ModelFetchOneSummary arg cannot be null" );

		Model entity = null;
		UUID id = summary.getModelId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Model using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Models
	 *
	 * @return 	List<Model>
	 */
    public List<Model> getAllModel() {
		List<Model> list = projector.findAll( new FindAllModelQuery() );
		return list;
	}

	/**
	 * assign Workspace on Model
	 * @param		command AssignWorkspaceToModelCommand
	 */
	public void assignWorkspace( AssignWorkspaceToModelCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignWorkspace(command.getModelId(), command.getAssignment());

	}

